from __future__ import annotations

import base64
import subprocess
import zlib

PATCH_B64 = ""


def main() -> None:
    patch = zlib.decompress(base64.b64decode(PATCH_B64))
    subprocess.run(
        ["git", "apply", "--whitespace=fix", "-"],
        input=patch,
        check=True,
    )


if __name__ == "__main__":
    main()
